10	
11	```ts
12	// params.ts
13	chat: { radius: 150, nearIn: 140, textMax: 200, linesMax: 4, marksMax: 4, msgBytes: 1024, ratePerWin: 5, rateWinMs: 10000,
14	        ackMs: 4000, nearTickMs: 500, bubbleMs: 5000, bubbleChars: 60, historyMax: 60 }
