31	
32	```ts
33	test('exSanitizeChat: giữ chữ thường, cắt khoảng trắng', () => { assert.equal(exSanitizeChat('  xin chào  '), 'xin chào'); });
34	test('exSanitizeChat: rỗng / chỉ trắng / chỉ ký tự ẩn / không phải chuỗi → null', () => {
35	  for (const v of ['', '   ', '\n\n', '\u200B\u200E', '\u3164', 5, null, undefined, {}]) assert.equal(exSanitizeChat(v as any), null);
36	});
37	test('exSanitizeChat: bỏ điều khiển và bidi, giữ xuống dòng và ZWJ', () => {
38	  assert.equal(exSanitizeChat('a\u0000b\u202Ec\r\nd'), 'abc\nd');
39	  assert.equal(exSanitizeChat('👨\u200D👩\u200D👧'), '👨\u200D👩\u200D👧');
40	});
41	test('exSanitizeChat: giữ ZWNJ (hi / fa), bỏ surrogate lẻ', () => {
42	  assert.equal(exSanitizeChat('a‌b'), 'a‌b');
43	  assert.equal(exSanitizeChat('a\uD83Db'), 'ab');
44	  assert.ok(JSON.stringify({ t: 'chat', id: 1, text: exSanitizeChat('\uD83D'.repeat(300) + 'x') }).length < 1024);
45	});
46	test('exSanitizeChat: tối đa 4 dòng, phần sau nối bằng khoảng trắng', () => { assert.equal(exSanitizeChat('1\n2\n3\n4\n5\n6'), '1\n2\n3\n4 5 6'); });
47	test('exSanitizeChat: cắt 200 code point (emoji tính 1)', () => {
48	  assert.equal([...exSanitizeChat('x'.repeat(500))!].length, 200);
49	  assert.equal([...exSanitizeChat('😀'.repeat(300))!].length, 200);
50	});
51	test('exSanitizeChat: dấu chồng quá 4 liên tiếp bị dồn còn 4', () => { assert.equal(exSanitizeChat('a' + '\u0301'.repeat(50) + 'b'), 'a' + '\u0301'.repeat(4) + 'b'); });
52	test('exSanitizeChat: HTML giữ nguyên là chữ', () => { assert.equal(exSanitizeChat('<img src=x onerror=alert(1)>'), '<img src=x onerror=alert(1)>'); });
53	test('exIsBadText: chặn theo từ, không chặn chuỗi con', () => {
54	  for (const s of ['fuck you', 'đồ lồn', 'du ma may', 'what a BITCH']) assert.equal(exIsBadText(s), true, s);
55	  for (const s of ['cut the rope', 'mishit', 'Dickson ơi', 'lớn quá', 'buổi sáng đẹp', 'các bạn', 'cac ban oi', 'lon nuoc', 'hello <b>']) assert.equal(exIsBadText(s), false, s);
56	});
