           |  { t: 'chatAck'; id: number; n?: number; why?: ChatWhy }
export function exSanitizeChat(raw: unknown): string | null;   // spec §7
// badwords.ts
export function exIsBadText(text: string): boolean;            // so theo từ, spec §7
```

