300	+export function exSanitizeChat(raw: unknown): string | null {
301	+  if (typeof raw !== 'string') return null;
302	+  const C = multiParams.chat;
303	+  let s = raw.replace(/\r\n?/g, '\n').replace(/\t/g, ' ')
